#[allow(non_snake_case)] fn ROTLEFT(a: u32, b: u32) -> u32 { (a).rotate_left(b) }
#[allow(non_snake_case)] fn ROTRIGHT(a: u32, b: u32) -> u32 { (a).rotate_right(b) }
#[allow(non_snake_case)] fn CH(x: u32, y: u32, z: u32) -> u32 { (((x) & (y)) ^ (!(x) & (z))) }
#[allow(non_snake_case)] fn MAJ(x: u32, y: u32, z: u32) -> u32 { (((x) & (y)) ^ ((x) & (z)) ^ ((y) & (z))) }
#[allow(non_snake_case)] fn EP0(x: u32) -> u32 { (ROTRIGHT(x,2) ^ ROTRIGHT(x,13) ^ ROTRIGHT(x,22)) }
#[allow(non_snake_case)] fn EP1(x: u32) -> u32 { (ROTRIGHT(x,6) ^ ROTRIGHT(x,11) ^ ROTRIGHT(x,25)) }
#[allow(non_snake_case)] fn SIG0(x: u32) -> u32 { (ROTRIGHT(x,7) ^ ROTRIGHT(x,18) ^ ((x) >> 3)) }
